#if LIBRA_VERSION == 2
// ETA Extension Estimate (until the ETA's actuator has a controller)

constexpr double kEtaVel = 0.0;          // m/s, actuation rate (TODO: measure)
constexpr int kEtaUpdatePeriodMs = 100;  // how often the estimate advances
#endif

//------------------------------------------------------------------------------
// !Class Helpers
//------------------------------------------------------------------------------

/**
 * @brief Moves the arm to the given joint angles.
 *
 * @param targets Joint angles, indexed by `Joint::Name` (deg)
 */
void MainWindow::SendJointTargets(const std::vector<double>& targets) {
    std::vector<double> actuator_targets(Actuator::kUndefined, 0.0);

    // Lambdas to improve readability of conversions (joint -> actuator)
    auto convert_and_set_simple = [&](Actuator::Name name, double val) {
        actuator_targets[name] = Actuator::JointToActuatorSimple(name, val);
    };
#if LIBRA_VERSION == 1
    auto convert_and_set_diff = [&](Actuator::Name name, double roll,
                                    double pitch) {
        actuator_targets[name] = Actuator::JointToActuatorDifferential(name,
                                                                       roll,
                                                                       pitch);
    };
#endif

    // Convert joint angles to actuator command angles
#if LIBRA_VERSION == 1
    const double roll = targets[Joint::Name::kRoll];
    const double pitch = targets[Joint::Name::kPitch];

    convert_and_set_diff(Actuator::kMA, roll, pitch);
    convert_and_set_diff(Actuator::kMB, roll, pitch);
    convert_and_set_simple(Actuator::kJ1, targets[Joint::Name::kJ1]);
    convert_and_set_simple(Actuator::kJ2, targets[Joint::Name::kJ2]);
    convert_and_set_simple(Actuator::kJ3, targets[Joint::Name::kJ3]);
#elif LIBRA_VERSION == 2
    convert_and_set_simple(Actuator::kYaw, targets[Joint::Name::kYaw]);
    convert_and_set_simple(Actuator::kPitch, targets[Joint::Name::kPitch]);
#endif

    if (debug_mode_) {
        std::stringstream command_ss;
        command_ss << std::fixed << std::setprecision(2)
                   << "Sending movement command (deg): ";

        for (int i = 0; i < Joint::Name::kUndefined; ++i) {
            const auto joint = static_cast<Joint::Name>(i);
            command_ss << Joint::NameEnumToString(joint) << "="
                       << targets[joint];

            if (i < Joint::Name::kUndefined - 1) {
                command_ss << ", ";
            }
        }

        logger_->Debug(command_ss.str());
    }

    // Send command(s)
#if LIBRA_VERSION == 1
    emit CommandHebi(actuator_targets);
#elif LIBRA_VERSION == 2
    emit CommandEpos({actuator_targets[Actuator::kYaw]});
    emit CommandHebi({actuator_targets[Actuator::kPitch]});
#endif

    previous_target_ = std::exchange(current_target_, targets);

    // UI widgets
    UpdateActuatorControls();
}

#if LIBRA_VERSION == 2
/**
 * @brief Starts, stops, or reverses the ETA extension estimate.
 *
 * @param vel Extension velocity (m/s); negative = retracting
 *
 * @todo The ETA's actuator is currently incapable of being digitally
 *       controlled, so its extension is estimated based on two things:
 *       (1) a known constant rate, and (2) manual user input on whether the ETA
 *       is moving and in which direction. Replace with the controller's
 *       feedback once it has one.
 */
void MainWindow::SetEtaVel(const double& vel) {
    UpdateEtaExtension();  // finish the previous motion, restart the clock
    eta_vel_ = vel;

    // Only one direction at a time
    ui_->pb_eta_extend->setChecked(vel > 0.0);
    ui_->pb_eta_retract->setChecked(vel < 0.0);

    if (vel == 0.0) {
        eta_timer_->stop();
    } else {
        eta_timer_->start(kEtaUpdatePeriodMs);
    }

    logger_->Info("ETA velocity set to "
                  + Motion::FormatNum(vel * Motion::kMmPerM) + " mm/s at "
                  + Motion::FormatNum(motion_controller_->GetEtaExtension()
                                      * Motion::kMmPerM)
                  + " mm (estimated)");
}

/**
 * @brief Advances the ETA extension estimate by time since last update.
 */
void MainWindow::UpdateEtaExtension() {
    const auto now = std::chrono::steady_clock::now();
    const double dt_s = std::chrono::duration<double>(now - eta_time_).count();
    eta_time_ = now;

    if (eta_vel_ == 0.0) {
        return;
    }

    // Measured from min. extension
    const double extension = std::max(0.0, motion_controller_->GetEtaExtension()
                                               + (eta_vel_ * dt_s));
    emit ReportEtaExtension(extension);

    if (extension == 0.0) {  // fully retracted, nothing left to estimate
        eta_vel_ = 0.0;
        SetEtaVel(0.0);
    }
}
#endif

//------------------------------------------------------------------------------
// !Buttons
//------------------------------------------------------------------------------

/**
 * @brief Sends the target spin boxes' values to all actuators.
 */
void MainWindow::on_pb_arm_start_clicked() {
    std::vector<double> targets(Motion::kNumJoints, 0.0);
    for (const auto& [joint, spin_box] : target_spin_box_map_) {
        targets[joint] = spin_box->value();
    }

    SendJointTargets(targets);
}

/**
 * @brief Pauses trajectory playback and stops the ETA estimate, if active.
 *
 * @note The actuators themselves are stopped via signals (see
 *       `InitializeThreads()`).
 */
void MainWindow::on_pb_arm_stop_clicked() {
#if LIBRA_VERSION == 2
    // NOTE: assumes a LIBRA App "STOP" means the ETA has also been stopped
    if (eta_vel_ != 0.0) {
        SetEtaVel(0.0);
    }
#endif

    if (!trajectory_playing_) {
        return;
    }

    logger_->Info("Trajectory paused at step "
                  + GetTrajectoryStepText().toStdString());
    SetTrajectoryPlaying(false);
}

/**
 * @brief Moves all actuators back to the previous target.
 *
 * @note Only goes back one target; button stays disabled until a new target is
 *       sent (so an accidental multi-click can't move the arm further).
 */
void MainWindow::on_pb_arm_return_clicked() {
    logger_->Info("Returning to the previous target");

    SendJointTargets(previous_target_);
    previous_target_ = current_target_;

    UpdateActuatorControls();
}

/**
 * @brief Requests the motion mode picked by the user, if its requirements are
 *        met; otherwise explains what's missing and resets to the current mode.
 *
 * @param index Picked list item
 *
 * @see SetMotionMode
 */
void MainWindow::on_cb_motion_mode_activated(int index) {
    const auto mode = static_cast<Motion::MotionMode>(
        ui_->cb_motion_mode->itemData(index).toInt());
    if (mode == motion_mode_) {
        return;
    }

    // Check the mode's requirements
    QString missing;
    if (mode != Motion::MotionMode::kManual
        && !ui_->a_water_cw_disconnect->isEnabled()) {
        missing = "a connected CW (see \"Water\" menu)";
    }
#if LIBRA_VERSION == 2
    if (missing.isEmpty() && Motion::UsesMotionController(mode)
        && motion_controller_->GetCalibration() != Motion::Calibration::kFull) {
        missing = "arm and friction calibrations (see \"Motion Control\" menu)";
    }
#endif

    if (!missing.isEmpty()) {
        const auto name = QString::fromStdString(
            Motion::MotionModeEnumToString(mode));
        logger_->Warn(name.toStdString() + " mode needs "
                      + missing.toStdString() + "; staying in the current mode");
        QMessageBox::warning(this, "Motion Mode",
                             name + " mode needs " + missing + ".");

        ui_->cb_motion_mode->setCurrentIndex(
            ui_->cb_motion_mode->findData(static_cast<int>(motion_mode_)));
        return;
    }

    SetMotionMode(mode);
}

#if LIBRA_VERSION == 2
/**
 * @brief Releases or takes back control of LIBRA-II's pitch joint (spins freely
 *        when released). Useful for simulating loss of power (while retaining
 *        control) or moving the arm by other means.
 *
 * @param checked Whether to release the pitch joint
 *
 * @note Only asks for confirmation if the arm is moving (i.e., assumes the arm
 *       is balanced if it's idle).
 */
void MainWindow::on_pb_release_pitch_toggled(bool checked) {
    if (checked && arm_moving_) {
        const auto reply = QMessageBox::warning(
            this, "Release Pitch",
            "The arm is currently in motion!\n"
            "Releasing the pitch joint cancels the active move; the arm will "
            "fall unless the CW is balanced.\n\n"
            "Continue?",
            QMessageBox::Yes | QMessageBox::No, QMessageBox::No);
        if (reply != QMessageBox::Yes) {
            logger_->Info("Pitch release cancelled by user");

            const QSignalBlocker blocker(ui_->pb_release_pitch);  // no re-emit
            ui_->pb_release_pitch->setChecked(false);

            return;
        }
    }

    emit EnablePitchRelease(checked);
}

/**
 * @brief Tells the ETA extension estimate the ETA started or stopped extending.
 *
 * @param checked Whether the ETA is extending
 *
 * @see MainWindow::SetEtaVel
 */
void MainWindow::on_pb_eta_extend_clicked(bool checked) {
    SetEtaVel(checked ? kEtaVel : 0.0);
}

/**
 * @brief Tells the ETA extension estimate the ETA started or stopped
 *        retracting.
 *
 * @param checked Whether the ETA is retracting
 *
 * @see MainWindow::SetEtaVel
 */
void MainWindow::on_pb_eta_retract_clicked(bool checked) {
    SetEtaVel(checked ? -kEtaVel : 0.0);
}
#endif
